package com.splendordashboard;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class DiagnosticsActivity extends Activity{TextView t;public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,18,24,18);l.setBackgroundColor(Color.rgb(5,7,8));t=new TextView(this);t.setTextColor(Color.WHITE);t.setTextSize(18);l.addView(t);Button back=new Button(this);back.setText("BACK");back.setOnClickListener(v->finish());l.addView(back);setContentView(l);refresh();}void refresh(){t.setText("DIAGNOSTICS\n\nApp version 1.0.0\nAndroid "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nDevice "+Build.MANUFACTURER+" "+Build.MODEL+"\n\nLocation permission: "+(checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")==0?"granted":"not granted")+"\n\nThis screen is intentionally native/offline and reports the device/runtime state without requiring network access.");}}